def _validate():
    assert len(FRQ_QUIZZES) == 24, len(FRQ_QUIZZES)
    titles = []
    n_items = 0
    subjects = []
    for q in FRQ_QUIZZES:
        titles.append(q["title"])
        subjects.append(q["subject"])
        assert q["kind"] == "generated"
        assert q["estimatedMinutes"] == 40
        assert q["difficultyTier"] == 2
        assert "id" not in q
        assert set(["frq-practice", "wave-7", "ced-aligned", "generated", "with-solutions"]).issubset(set(q["tags"]))
        assert len(q["items"]) == 5
        for it in q["items"]:
            assert "id" not in it
            assert it["format"] == "frq_half"
            assert it["difficultyTier"] == 2
            assert 3 <= len(it["visibleSteps"]) <= 5
            assert 1 <= len(it["blankSteps"]) <= 3
            assert len(it["hints"]) == 3
            n_items += 1
    assert n_items == 120, n_items
    assert len(set(titles)) == 24
    expected = [
        "AP Physics 1",
        "AP Physics 2",
        "AP Physics C: Mechanics",
        "AP Physics C: E&M",
        "AP Calculus AB/BC",
        "AP Chemistry",
        "AP Biology",
        "AP Statistics",
    ]
    for i, subj in enumerate(expected):
        chunk = subjects[i * 3 : (i + 1) * 3]
        assert chunk == [subj, subj, subj], chunk
        waves = [FRQ_QUIZZES[i * 3 + j]["title"] for j in range(3)]
        assert "Wave 7A" in waves[0] and "Wave 7B" in waves[1] and "Wave 7C" in waves[2]
    return len(FRQ_QUIZZES), n_items


_validate()

if __name__ == "__main__":
    n_q, n_i = _validate()
    print(len(FRQ_QUIZZES))
    print(f"OK: {n_q} quizzes, {n_i} FRQs")
